perspectives.style:
@settings {
  template: systems;
  element-color: categorize("TRL", heat);
  element-shape: categorize("Element Type");
  direct-decorations: false;
  theme: light;
  quality: best;
  background-color: white;
  include: process, feedstock, undefined, connection, loop;
  font-size: 31;
}

/* Intermediate */
element["element type"="Process"][!"maturity"] {
  color: #a7a7a7;
}

/* Process */
element["element type"="Process"] {
  shape: diamond;
}

/* Medium TRL */
element["element type"="process"]["maturity score"="medium"] {
  color: #fdc16f;
  shape: diamond;
}

/* Low TRL */
element["element type"="process"]["maturity score"="low"] {
  color: #f6553c;
  shape: diamond;
}

/* Good TRL */
element["element type"="process"]["maturity score"="high"] {
  color: #74c89e;
  shape: diamond;
}

/* Mature TRL */
element["element type"="process"]["maturity score"="fully mature"] {
  color: #3596c0;
  shape: diamond;
}

/* Hotspot products */
element["hotspot rank"] {
  color: #aaa9d1;
}

/* Dedicated alternatives */
element["tags"="Dedicated alternatives"] {
  color: #3eaba0;
}

/* Feedstock */
element["element type"="Feedstock"] {
  size: 5;
  color: #ffffff;
}

/* Top 15 hotspot products */
element["hotspot rank"<"16"] {
  bullseye-color: #fec05a;
}

@settings {
