}

/* Low TRL */
element["element type"="Process"]["maturity"="Low"] {
  color: #f53b23;
  shape: diamond;
}

/* Good TRL */
element["element type"="Process"]["maturity"="High"] {
  color: #74c89e;
  shape: diamond;
}

/* Mature TRL */
element["element type"="Process"]["maturity"="Fully mature"] {
  color: #3596c0;
  shape: diamond;
}

/* Short listed products */
element["tags"="Short listed"] {
  color: #5e4fa2;
}

/* Dedicated alternatives */
element["tags"="Dedicated alternatives"] {
  color: #3eaba0;
}

connection["maturity"="High"] {
  color: #74c89e;
}

connection["maturity"="Medium"] {
  color: #fdc16f;
}

connection["maturity"="Low"] {
  color: #b60027;
}

connection["maturity"="Fully mature"] {
  color: #3596c0;
}

/* Focus */
element["tags"*="Focus"] {
  shadow-color: #fd7234;
  shadow-opacity: 0.8;
  shadow-size: 1.3;
}

/* Has LCAs */
element["lca (references)"] {
  bullseye-color: #74c89e;
}

element {
  flag: "Tags" with pink "Key intermediate", cyan "Key product";
}

